import logging
import time

from .api import CnumRestApi
from .exceptions import OperationFailed

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class Cnum:

    def __init__(self, nodes_factory):
        self.api = CnumRestApi(nodes_factory.web_url, nodes_factory.web_username, nodes_factory.web_password)
        self.nodes_factory = nodes_factory

    @property
    def was_node(self):
        return self.nodes_factory.get_was_node()

    def execute_operation(self, operation, ne_id_value, ne_id_type='dn', ldap_access_type=None,
                          ip_type=None, include_correlated_nes=None, timeout=120):
        """
        Perform CNUM Activation/Deactivation/Reactivation on a specific network element.
        Distinguished Name or Presentation Name must be specified as input for the network element.

        Example output::

            {
                "activationState": None,
                "completionTime": None,
                "errors": [],
                "statusMsg": "1 out of 1 Operation(s) scheduled are completed. "
                             "Successful = 1, Partly Successful = 0, Failed = 0, Ongoing = 0",
                "startTimeStamp": "15/06/2023 09:18:55 GMT",
                "operationStatus": "Completed"
            }

        :param string operation: Specifies which CNUM operation is to be triggered for specified network element.
            Allowed values: `Activation`, `Deactivation` or `Reactivation`.
        :param string|list(dict) ne_id_value: Specifies network element(s) for which CNUM operation is to be triggered.
            If `ne_id_type` is `dn`, then NE's Distinguished Name must be set (as registered in Monitor).
            If `ne_id_type` is `name`, then NE's Presentation Name must be set (as configured in NE Integration Wizard).
            If `ne_id_type` is `input_file`, then list of NEs must be specified in list(dict) format, where each dict
            must contain at least `dnName` attribute:
                - dnName (string): (Mandatory) NE’s Distinguished Name.
                - ldapAccessType (string): (Optional): Allowed values: `PREFER TLS` or `STARTTLS`
                - ipType (string): (Optional): Allowed values: `IPv4` or `IPv6`
            If `ldapAccessType` and/or `ipType` attribute are not specified, then the values configured in
            `ldap_access_type` and/or `ip_type` are used. If `ldap_access_type` and/or `ip_type` are not specified,
            then default values supported by the specified network element type are used.
        :param string ne_id_type: Allowed values:
            - `dn` if NE’s Distinguished Name is set as `ne_id_value`.
            - `name` if NE’s Presentation Name is set as `ne_id_value`.
            - `input_file` if list of NEs is set as `ne_id_value`.
        :param string ldap_access_type: LDAP Access type to be configured in network element while triggering CNUM
            activation operation. Optional for `Activation` operation type. Not needed or ignored if specified,
            for `Deactivation` and `Reactivation` operation types. Allowed values `PREFER TLS` or `STARTTLS`.
            If not specified during activation, then the default LDAP Access Type supported by the specified
            network element type is used.
        :param string ip_type: IP type configured in network element while triggering CNUM activation operation.
            Optional for `Activation` operation type. Not needed or ignored if specified, for `Deactivation` and
            `Reactivation` operation types. Allowed values: `IPv4` or `IPv6`. If not specified during activation,
            then the default IP Type supported by the specified network element type is used.
        :param bool include_correlated_nes: IP type configured in network element while triggering CNUM operation.
            If `False`, then triggered CNUM operation is performed only on the specified network element
            and not on co-related network elements even if they exist. If not set, then the default value is `False`.
            This flag is provided for network elements that have a PARENT-CHILD correlation. That is, NADA adaptation
            parameter correlationType equals PARENT or CHILD, e.g. RNC and VNF. For such correlated network elements
            it is recommended to have same CNUM status.
        :param int timeout: Timeout for executing operation.

        :return: Status of operation.
        :rtype: dict
        """
        response_json = self.api.trigger_operation(
            operation, ne_id_value, ne_id_type, ldap_access_type, ip_type, include_correlated_nes
        )
        if response_json['status'] == 'Started' and response_json['operationId']:
            return self.wait_for_status(response_json['operationId'], timeout)
        raise OperationFailed(response_json['errorMessage'])

    def wait_for_status(self, operation_id, timeout=120):
        """
        Wait for operation status indicating completion.

        :param string operation_id: CNUM operation Job ID for which status is to be obtained,
            e.g. `neac.cnum.1684763709257`
        :param int timeout: Timeout for completing operation.

        :return: Status of operation. Example output the same as for :meth:`execute_operation`.
        :rtype: dict
        """
        end_time = time.monotonic() + timeout
        while time.monotonic() < end_time:
            time.sleep(5)
            response_json = self.api.get_operation_status(operation_id)
            if response_json['operationStatus'] == 'Completed':
                if 'Failed = 0' in response_json['statusMsg']:
                    return response_json
                else:
                    raise OperationFailed(response_json['statusMsg'])
        raise TimeoutError(response_json['statusMsg'])

    def get_summary(self, ne_id_value, ne_id_type='dn', csv_format=False):
        """
        Generate and get content of report summarizing the CNUM status for all network elements provided as input.

        Example output for `list(dict)` type::

            [
                {
                    'distinguished_name': 'PLMN-PLMN/MRBTS-1234',
                    'ne_name': '',
                    'ne_release': 'SBTS23R1',
                    'ne_type': 'MRBTS',
                    'ldap_access_type': 'StartTLS',
                    'ip_version': 'IPv4',
                    'cnum_status': 'Failed activation',
                    'time_of_last_action': '2023-06-15 12:07:30.624'
                },
                {
                    'distinguished_name': 'PLMN-PLMN/MRBTS-4321',
                    'ne_name': '',
                    'ne_release': 'SBTS23R1',
                    'ne_type': 'MRBTS',
                    'ldap_access_type': 'PREFER TLS',
                    'ip_version': 'IPv4',
                    'cnum_status': 'Activated',
                    'time_of_last_action': '2023-06-15 12:18:50.652'
                }
            ]

        :param string|list(dict) ne_id_value: Specifies network element(s) for which CNUM summary is to be generated.
            If `ne_id_type` is `dn`, then NE's Distinguished Name must be set (as registered in Monitor).
            If `ne_id_type` is `name`, then NE's Presentation Name must be set (as configured in NE Integration Wizard).
            If `ne_id_type` is `input_file`, then list of NEs must be specified in list(dict) format, where each dict
            must contain ``dnName`` attribute:
                - dnName (string): NE’s Distinguished Name.
        :param string ne_id_type: Allowed values:
            - `dn` if NE’s Distinguished Name is set as `ne_id_value`.
            - `name` if NE’s Presentation Name is set as `ne_id_value`.
            - `input_file` if list of NEs is set as `ne_id_value`.
        :param bool csv_format: If `True`, returns report in CSV format as string. Otherwise as list(dict).

        :return: Content of report summarizing the CNUM status for all network elements provided as input.
        :rtype: string|list(dict)
        """
        response_json = self.api.generate_summary(ne_id_value, ne_id_type)
        if response_json['summaryStatus'] == 'successful':
            with self.was_node as ssh:
                summary_path = response_json['summaryPath']
                try:
                    summary = self._decode(ssh.get_file_content(summary_path))
                    logger.debug(f'Content of {summary_path}: \n{summary}')
                finally:
                    ssh.execute_command(f'rm -f {summary_path}', ignore_stderr=True, ignore_rc=True)
            if not csv_format:
                summary = self._convert_csv_to_list(summary)
            return summary
        raise OperationFailed()

    def get_report(self, csv_format=False):
        """
        Generate and get content of report summarizing the current CNUM status of all network elements
        that are integrated to the NetAct Cluster and support CNUM provisioning.

        Example output for `list(dict)` type::

            [
                {
                    'cnum_status': 'Activated',
                    'distinguished_name': 'PLMN-PLMN/MRBTS-12345',
                    'ip_version': 'IPv4',
                    'ldap_access_type': 'PREFER TLS',
                    'maintenance_region': 'MRC-COMMON/MR-COMMON',
                    'ne_name': 'null',
                    'ne_release': 'SBTS23R2',
                    'ne_type': 'MRBTS',
                    'time_of_last_action': '2023-06-15 07:08:09.000'
                },
                {
                    'cnum_status': 'Deactivated',
                    'distinguished_name': 'PLMN-PLMN/MRBTS-54321',
                    'ip_version': 'IPv4',
                    'ldap_access_type': 'PREFER TLS',
                    'maintenance_region': 'MRC-COMMON/MR-COMMON',
                    'ne_name': 'null',
                    'ne_release': 'SBTS23R4',
                    'ne_type': 'MRBTS',
                    'time_of_last_action': '2023-05-31 11:53:58.909'
                },
                {
                    'cnum_status': 'Not configured',
                    'distinguished_name': 'PLMN-PLMN/MRBTS-11111',
                    'ip_version': 'IPv4',
                    'ldap_access_type': 'StartTLS',
                    'maintenance_region': 'MRC-COMMON/MR-COMMON',
                    'ne_name': 'null',
                    'ne_release': 'SBTS23R4',
                    'ne_type': 'MRBTS',
                    'time_of_last_action': ''
                },
                ...
            ]

        :param bool csv_format: If `True`, returns report in CSV format as string. Otherwise as list(dict).

        :return: Content of report summarizing the current CNUM status of all network elements
            that are integrated to the NetAct Cluster and support CNUM provisioning.
        :rtype: string|list(dict)
        """
        response_json = self.api.generate_report()
        if response_json['reportStatus'] == 'successful':
            with self.was_node as ssh:
                report_path = response_json['reportPath']
                try:
                    report = self._decode(ssh.get_file_content(report_path))
                    logger.debug(f'Content of {report_path}: \n{report}')
                finally:
                    ssh.execute_command(f'rm -f {report_path}', ignore_stderr=True, ignore_rc=True)
            if not csv_format:
                report = self._convert_csv_to_list(report)
            return report
        raise OperationFailed(response_json['failureReason'])

    @staticmethod
    def _convert_csv_to_list(csv_content):
        """
        Convert csv format to list(dict)
        """
        csv_lines = csv_content.splitlines()
        csv_header = csv_lines[0].lower().replace(' ', '_')
        csv_values = csv_lines[1:]
        return [dict(zip(csv_header.split(','), line.split(','))) for line in csv_values]

    @staticmethod
    def _decode(s):
        return s.decode('utf-8') if isinstance(s, bytes) else s
